async function enviarPorEmail({ fileName, data, mimeType = "application/x-sqlite3", assunto, corpo }) {
	if (isFilesystemDisponivel() && isShareDisponivel()) try {
		const base64Data = typeof data === "string" ? stringToBase64(data) : uint8ArrayToBase64(data);
		await Filesystem.writeFile({
			path: fileName,
			data: base64Data,
			directory: Directory.Cache
		});
		const uriResult = await Filesystem.getUri({
			path: fileName,
			directory: Directory.Cache
		});
		await Share.share({
			title: assunto || `Backup Em Dia - ${fileName}`,
			text: corpo || "Segue em anexo o arquivo de backup do aplicativo Em Dia (.sqlite).",
			files: [uriResult.uri],
			dialogTitle: "Enviar backup por e-mail"
		});
		return;
	} catch (err) {
		console.warn("Aviso: Falha ao enviar por e-mail via Share nativo:", err);
	}
	downloadNavegador(fileName, data, mimeType);
}
/**
* Exporta ou compartilha um arquivo genérico.
* Usa files: [uri] para que o Android reconheça como arquivo anexado real.
*/
async function exportarOuCompartilharArquivo({ fileName, data, mimeType, dialogTitle = "Salvar backup", title }) {
	if (isFilesystemDisponivel() && isShareDisponivel()) try {
		const base64Data = typeof data === "string" ? stringToBase64(data) : uint8ArrayToBase64(data);
		await Filesystem.writeFile({
			path: fileName,
			data: base64Data,
			directory: Directory.Cache
		});
		const uriResult = await Filesystem.getUri({
			path: fileName,
			directory: Directory.Cache
		});
		await Share.share({
			title: title || fileName,
			files: [uriResult.uri],
			dialogTitle: dialogTitle || "Salvar backup"
		});
		return { fileName };
	} catch (err) {
		console.warn("Aviso: Falha ao compartilhar via Share nativo:", err);
	}
	downloadNavegador(fileName, data, mimeType);
	return { fileName };
}
