/**
* Camada de Acesso a Dados (DAO / Repository)
* Todas as operações utilizam consultas SQL parametrizadas,
* integridade monetária em CENTAVOS (INTEGER),
* derivação dinâmica de status atrasado e persistência debounced.
*/
async function listarCategorias() {
	const stmt = (await getDb()).prepare(`
    SELECT id, nome, cor 
    FROM categorias 
    ORDER BY 
      CASE WHEN LOWER(nome) = 'gastos' THEN 0 
           WHEN LOWER(nome) = 'despesas' THEN 1 
           ELSE 2 END, 
      nome ASC
  `);
	const categorias = [];
	while (stmt.step()) {
		const row = stmt.getAsObject();
		categorias.push({
			id: row.id,
			nome: row.nome,
			cor: row.cor
		});
	}
	stmt.free();
	return categorias;
}
async function criarCategoria(nome, cor) {
	const db = await getDb();
	db.run("INSERT INTO categorias (nome, cor) VALUES (?, ?);", [nome.trim(), cor.trim()]);
	const res = db.exec("SELECT last_insert_rowid() as id;");
	persistirDb();
	return res[0]?.values[0]?.[0];
}
async function atualizarCategoria(id, nome, cor) {
	(await getDb()).run("UPDATE categorias SET nome = ?, cor = ? WHERE id = ?;", [
		nome.trim(),
		cor.trim(),
		id
	]);
	persistirDb();
}
async function excluirCategoria(id) {
	try {
		const db = await getDb();
		if ((db.exec("SELECT COUNT(*) as total FROM contas WHERE categoria_id = ?;", [id])[0]?.values[0]?.[0] || 0) > 0) return {
			success: false,
			message: "Não é possível excluir esta categoria pois há lançamentos vinculados a ela."
		};
		db.run("DELETE FROM categorias WHERE id = ?;", [id]);
		persistirDb();
		return { success: true };
	} catch (err) {
		return {
			success: false,
			message: err?.message || "Erro ao excluir categoria."
		};
	}
}
async function criarConta(input) {
	const hoje = getHojeIso();
	const valorTotalCentavos = parseMoedaParaCentavos(input.valor_total);
	return await executarEmTransacao((db) => {
		let categoriaId = input.categoria_id;
		if (!db.exec("SELECT id FROM categorias WHERE id = ?;", [categoriaId])[0]?.values?.length) {
			const anyCat = db.exec("SELECT id FROM categorias ORDER BY id ASC LIMIT 1;");
			if (anyCat[0]?.values?.length) categoriaId = anyCat[0].values[0][0];
			else {
				db.run("INSERT INTO categorias (nome, cor) VALUES ('Gastos', '#2563eb');");
				categoriaId = db.exec("SELECT last_insert_rowid() as id;")[0]?.values[0]?.[0] || 1;
			}
		}
		const diaBase = extrairPartesData(input.data_primeiro_vencimento).dia;
		const freqRec = input.tipo === "recorrente" ? input.frequencia_recorrencia || "mensal" : null;
		db.run(`INSERT INTO contas (descricao, categoria_id, valor_total, tipo, forma_pagamento, observacoes, data_criacao, frequencia_recorrencia, dia_base)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);`, [
			input.descricao.trim(),
			categoriaId,
			valorTotalCentavos,
			input.tipo,
			input.forma_pagamento || "Geral",
			input.observacoes ? input.observacoes.trim() : null,
			hoje,
			freqRec,
			diaBase
		]);
		const contaId = db.exec("SELECT last_insert_rowid() as id;")[0]?.values[0]?.[0];
		if (!contaId) throw new Error("Falha ao obter identificador da conta criada.");
		if (input.tipo === "unica") db.run(`INSERT INTO parcelas (conta_id, numero_parcela, total_parcelas, valor, data_vencimento, data_pagamento, status, valor_pago)
         VALUES (?, 1, 1, ?, ?, NULL, 'pendente', NULL);`, [
			contaId,
			valorTotalCentavos,
			input.data_primeiro_vencimento
		]);
		else if (input.tipo === "recorrente") {
			let dataVenc = input.data_primeiro_vencimento;
			for (let i = 0; i < 12; i++) {
				if (i > 0) dataVenc = calcularProximoVencimento(dataVenc, "mensal", diaBase);
				db.run(`INSERT INTO parcelas (conta_id, numero_parcela, total_parcelas, valor, data_vencimento, data_pagamento, status, valor_pago)
           VALUES (?, ?, 12, ?, ?, NULL, 'pendente', NULL);`, [
					contaId,
					i + 1,
					valorTotalCentavos,
					dataVenc
				]);
			}
		} else if (input.tipo === "parcelada") {
			const totalParcelas = Math.max(1, input.numero_parcelas || 1);
			let parcelasCentavos;
			if (input.modo_valor_parcelado === "total" || !input.modo_valor_parcelado && (input.observacoes?.includes("Porquinho") || input.descricao?.toLowerCase().includes("porquinho"))) parcelasCentavos = dividirEmParcelas(valorTotalCentavos, totalParcelas);
			else {
				const valParcCentavos = parseMoedaParaCentavos(input.valor_parcela !== void 0 && input.valor_parcela !== null ? input.valor_parcela : input.valor_total);
				parcelasCentavos = Array(totalParcelas).fill(valParcCentavos);
			}
			let dataVenc = input.data_primeiro_vencimento;
			for (let i = 0; i < totalParcelas; i++) {
				if (i > 0) dataVenc = calcularProximoVencimento(dataVenc, "mensal", diaBase);
				db.run(`INSERT INTO parcelas (conta_id, numero_parcela, total_parcelas, valor, data_vencimento, data_pagamento, status, valor_pago)
           VALUES (?, ?, ?, ?, ?, NULL, 'pendente', NULL);`, [
					contaId,
					i + 1,
					totalParcelas,
					parcelasCentavos[i],
					dataVenc
				]);
			}
			db.run(`UPDATE contas 
         SET valor_total = (SELECT SUM(valor) FROM parcelas WHERE conta_id = contas.id)
         WHERE id = ?;`, [contaId]);
		}
		return contaId;
	});
}
async function excluirConta(contaId) {
	await executarEmTransacao((db) => {
		db.run("DELETE FROM parcelas WHERE conta_id = ?;", [contaId]);
		db.run("DELETE FROM contas WHERE id = ?;", [contaId]);
	});
}
async function editarParcelaEConta(dados) {
	const valorCentavos = parseMoedaParaCentavos(dados.valor);
	await executarEmTransacao((db) => {
		const res = db.exec("SELECT conta_id, numero_parcela, total_parcelas, status, valor FROM parcelas WHERE id = ?;", [dados.parcelaId]);
		if (!res[0]?.values?.length) throw new Error("Parcela não encontrada.");
		const contaId = res[0].values[0][0];
		const numParcela = res[0].values[0][1];
		const totalParcelas = res[0].values[0][2];
		db.run(`UPDATE parcelas 
       SET valor = ?, data_vencimento = ?
       WHERE id = ?;`, [
			valorCentavos,
			dados.data_vencimento,
			dados.parcelaId
		]);
		db.run(`UPDATE contas 
       SET descricao = ?, categoria_id = ?, forma_pagamento = ?, observacoes = ?
       WHERE id = ?;`, [
			dados.descricao.trim(),
			dados.categoria_id,
			dados.forma_pagamento || "Geral",
			dados.observacoes || null,
			contaId
		]);
		if (dados.escopo === "esta_e_proximas" && totalParcelas > 1) db.run(`UPDATE parcelas 
         SET valor = ?
         WHERE conta_id = ? AND numero_parcela > ? AND status != 'pago';`, [
			valorCentavos,
			contaId,
			numParcela
		]);
		else if (dados.escopo === "todas_da_conta" && totalParcelas > 1) db.run(`UPDATE parcelas 
         SET valor = ?
         WHERE conta_id = ? AND status != 'pago';`, [valorCentavos, contaId]);
		db.run(`UPDATE contas 
       SET valor_total = (SELECT SUM(valor) FROM parcelas WHERE conta_id = contas.id)
       WHERE id = ?;`, [contaId]);
		const valorGravado = db.exec("SELECT valor FROM parcelas WHERE id = ?;", [dados.parcelaId])[0]?.values[0]?.[0];
		if (valorGravado !== valorCentavos) {
			console.error("Divergência ao gravar parcela:", {
				valorDigitado: dados.valor,
				valorGravado,
				parcelaId: dados.parcelaId
			});
			throw new Error(`Divergência na gravação: valor gravado no SQLite (${valorGravado} centavos) difere do valor esperado (${valorCentavos} centavos).`);
		}
		if (dados.escopo === "esta_e_proximas" && totalParcelas > 1) {
			const verifyProx = db.exec("SELECT id, valor FROM parcelas WHERE conta_id = ? AND numero_parcela > ? AND status != 'pago';", [contaId, numParcela]);
			if (verifyProx[0]?.values) for (const row of verifyProx[0].values) {
				const pId = row[0];
				const pVal = row[1];
				if (pVal !== valorCentavos) {
					console.error("Divergência ao gravar parcela subsequente:", {
						valorDigitado: dados.valor,
						valorGravado: pVal,
						parcelaId: pId
					});
					throw new Error(`Divergência na parcela ${pId}: gravado ${pVal} centavos, esperado ${valorCentavos} centavos.`);
				}
			}
		}
	});
}
