/**
* Marca uma parcela como paga:
* - Se for recorrente, gera automaticamente a PRÓXIMA parcela pendente
*   com cálculo estrito de fim de mês e preservação do dia original.
*/
async function marcarParcelaComoPaga(parcelaId, dataPagamento, valorPago) {
	const hoje = getHojeIso();
	const dtPag = dataPagamento || hoje;
	await executarEmTransacao((db) => {
		const resParc = db.exec(`SELECT p.id, p.conta_id, p.valor, p.numero_parcela, p.data_vencimento,
              c.tipo, c.frequencia_recorrencia, c.dia_base, c.descricao, c.categoria_id
       FROM parcelas p
       INNER JOIN contas c ON p.conta_id = c.id
       WHERE p.id = ?;`, [parcelaId]);
		if (!resParc[0]?.values?.length) throw new Error("Parcela não encontrada.");
		const row = resParc[0].values[0];
		const contaId = row[1];
		const valorOriginal = row[2];
		const numParcela = row[3];
		const dataVencAtual = row[4];
		const tipoConta = row[5];
		const freqRecorrencia = row[6] || "mensal";
		const diaBaseOriginal = row[7] || extrairPartesData(dataVencAtual).dia;
		const valorPagoFinal = valorPago !== void 0 && valorPago !== null ? valorPago > 1e6 || Number.isInteger(valorPago) ? Math.round(valorPago) : reaisParaCentavos(valorPago) : valorOriginal;
		db.run(`UPDATE parcelas 
       SET status = 'pago', data_pagamento = ?, valor_pago = ?
       WHERE id = ?;`, [
			dtPag,
			valorPagoFinal,
			parcelaId
		]);
		if (tipoConta === "recorrente") {
			const qtdPendentes = db.exec(`SELECT COUNT(*) FROM parcelas WHERE conta_id = ? AND status = 'pendente';`, [contaId])[0]?.values[0]?.[0] || 0;
			if (qtdPendentes < 12) {
				const faltam = 12 - qtdPendentes;
				const resUltima = db.exec(`SELECT MAX(data_vencimento), MAX(numero_parcela) FROM parcelas WHERE conta_id = ?;`, [contaId]);
				let ultVenc = resUltima[0]?.values[0]?.[0] || dataVencAtual;
				let ultNum = resUltima[0]?.values[0]?.[1] || numParcela;
				for (let k = 0; k < faltam; k++) {
					ultVenc = calcularProximoVencimento(ultVenc, freqRecorrencia, diaBaseOriginal);
					ultNum++;
					db.run(`INSERT INTO parcelas (conta_id, numero_parcela, total_parcelas, valor, data_vencimento, data_pagamento, status, valor_pago)
             VALUES (?, ?, ?, ?, ?, NULL, 'pendente', NULL);`, [
						contaId,
						ultNum,
						ultNum,
						valorOriginal,
						ultVenc
					]);
				}
				db.run("UPDATE parcelas SET total_parcelas = ? WHERE conta_id = ?;", [ultNum, contaId]);
			}
		}
	});
}
/**
* Desfaz o pagamento de uma parcela
*/
async function desfazerPagamentoParcela(parcelaId) {
	await executarEmTransacao((db) => {
		const res = db.exec(`SELECT p.conta_id, p.numero_parcela, c.tipo 
       FROM parcelas p
       INNER JOIN contas c ON p.conta_id = c.id
       WHERE p.id = ?;`, [parcelaId]);
		if (!res[0]?.values?.length) return;
		const contaId = res[0].values[0][0];
		res[0].values[0][1];
		const tipo = res[0].values[0][2];
		db.run(`UPDATE parcelas 
       SET status = 'pendente', data_pagamento = NULL, valor_pago = NULL
       WHERE id = ?;`, [parcelaId]);
		if (tipo === "recorrente") {
			const qtd = db.exec(`SELECT COUNT(*) FROM parcelas WHERE conta_id = ? AND status = 'pendente';`, [contaId])[0]?.values[0]?.[0] || 0;
			if (qtd > 12) {
				const excedente = qtd - 12;
				db.run(`DELETE FROM parcelas WHERE id IN (
            SELECT id FROM parcelas WHERE conta_id = ? AND status = 'pendente' ORDER BY numero_parcela DESC LIMIT ?
          );`, [contaId, excedente]);
			}
		}
	});
}
/**
* Exclui uma parcela individual ou uma recorrente e suas futuras
*/
async function excluirParcela(parcelaId, escopoRecorrente) {
	await executarEmTransacao((db) => {
		const res = db.exec(`SELECT p.conta_id, p.numero_parcela, p.data_vencimento, c.tipo, c.frequencia_recorrencia, c.dia_base, c.valor_total
       FROM parcelas p
       INNER JOIN contas c ON p.conta_id = c.id
       WHERE p.id = ?;`, [parcelaId]);
		if (!res[0]?.values?.length) return;
		const contaId = res[0].values[0][0];
		const tipo = res[0].values[0][3];
		if (tipo === "recorrente" && escopoRecorrente === "esta_e_futuras") {
			db.run("DELETE FROM parcelas WHERE conta_id = ?;", [contaId]);
			db.run("DELETE FROM contas WHERE id = ?;", [contaId]);
			return;
		}
		db.run("DELETE FROM parcelas WHERE id = ?;", [parcelaId]);
		if ((db.exec("SELECT COUNT(*) as total FROM parcelas WHERE conta_id = ?;", [contaId])[0]?.values[0]?.[0] || 0) === 0) db.run("DELETE FROM contas WHERE id = ?;", [contaId]);
		else if (tipo === "recorrente") {
			if (!db.exec(`SELECT id FROM parcelas WHERE conta_id = ? AND status = 'pendente';`, [contaId])[0]?.values?.length) {
				const ult = db.exec(`SELECT data_vencimento, numero_parcela FROM parcelas WHERE conta_id = ? ORDER BY numero_parcela DESC LIMIT 1;`, [contaId]);
				if (ult[0]?.values?.length) {
					const ultVenc = ult[0].values[0][0];
					const ultNum = ult[0].values[0][1];
					const freq = res[0].values[0][4] || "mensal";
					const diaBase = res[0].values[0][5] || 1;
					const valor = res[0].values[0][6];
					const proxVenc = calcularProximoVencimento(ultVenc, freq, diaBase);
					db.run(`INSERT INTO parcelas (conta_id, numero_parcela, total_parcelas, valor, data_vencimento, data_pagamento, status, valor_pago)
             VALUES (?, ?, ?, ?, ?, NULL, 'pendente', NULL);`, [
						contaId,
						ultNum + 1,
						ultNum + 1,
						valor,
						proxVenc
					]);
				}
			}
		}
	});
}
async function prepararDadosRestauracao(parcelaId) {
	const db = await getDb();
	const resP = db.exec("SELECT conta_id FROM parcelas WHERE id = ?;", [parcelaId]);
	if (!resP[0]?.values?.length) return null;
	const contaId = resP[0].values[0][0];
	const resC = db.exec("SELECT id, descricao, categoria_id, valor_total, tipo, forma_pagamento, observacoes, data_criacao, frequencia_recorrencia, dia_base FROM contas WHERE id = ?;", [contaId]);
	if (!resC[0]?.values?.length) return null;
	const cRow = resC[0].values[0];
	const parcelasDaConta = (await listarParcelas({
		categoria_id: "todas",
		mesAno: "todos",
		status: "todos"
	})).filter((p) => p.conta_id === contaId);
	return {
		tipoExclusao: "conta",
		conta: {
			id: cRow[0],
			descricao: cRow[1],
			categoria_id: cRow[2],
			valor_total: cRow[3],
			tipo: cRow[4],
			forma_pagamento: cRow[5],
			observacoes: cRow[6],
			data_criacao: cRow[7],
			frequencia_recorrencia: cRow[8],
			dia_base: cRow[9]
		},
		parcelas: parcelasDaConta
	};
}
/**
* Exclui uma parcela individual retornando o snapshot para desfazer a exclusão
*/
async function excluirParcelaIndividual(parcelaId) {
	const dados = await prepararDadosRestauracao(parcelaId);
	if (!dados) throw new Error("Parcela não encontrada para exclusão.");
	const dadosParaRestaurar = {
		tipoExclusao: "parcela",
		conta: dados.conta,
		parcelas: dados.parcelas.filter((p) => p.id === parcelaId)
	};
	await excluirParcela(parcelaId, "apenas_esta");
	return dadosParaRestaurar;
}
